/** Replaceable browser adapter. Game rules and authored content live elsewhere. */
import {createClimb,choosePath,continueClimb,skipBonus,startEncounter,stepRun,inputRun,chooseReward,abandonRun,isTerminal,TICK_MS} from './rogue-run.js';
import {actionFor} from './handling-profile.js';
import {DEFAULT_CLIMB} from './climb-content.js';
import {objectiveLabel,objectiveStatus,objectiveHint,swordSize} from './climb-objectives.js';
import {serializeRun,restoreRun,MAX_SAVE_BYTES} from './rogue-save.js';
import {runView} from './rogue-view.js';
import {drawBoard,drawNext} from './render.js';
import {createComboLog,stepOf,comboHTML,comboName} from './combo-log.js';
import {createPlayout,finisherOf,showFinisher} from './finisher.js';
import {fitBoards} from './fit-boards.js';

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=ms=>{const s=Math.max(0,Math.ceil(ms/1000));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;};
const keyLabel=key=>({ArrowLeft:'←',ArrowRight:'→',ArrowUp:'↑',ArrowDown:'↓',Space:'Space',Escape:'Esc'})[key]??key.replace(/^Key|^Digit/,'');
const objective=e=>e.templateId?objectiveLabel(e.objective):e.kind==='duel'?`Defeat ${e.opponent.name}`:e.objective.kind==='survive'?`Survive ${clock(e.objective.target)}`:e.objective.kind==='blocks'?`Break ${e.objective.target} blocks`:`Score ${e.objective.target} points`;
const SAVE_KEY='rogue-run';
// Runs carry the content they started with. Show their relics with today's names and wording
// (same ids, same effects); the saved numbers still decide what they do.
const wording=u=>{const now=DEFAULT_CLIMB.upgrades.find(x=>x.id===u.id);return now?{...u,name:now.name,description:now.description,flavor:now.flavor??u.flavor,rarity:now.rarity??u.rarity}:u;};
const present=v=>v.kind==='climb'?{...v,offers:(v.offers||[]).map(wording),inventory:(v.inventory||[]).map(wording)}:v;
const effectName={scorePercent:'Clear points',chainBonus:'Extra chain points',breakerBonus:'Breaker chance',attackDelayMs:'Wave delay',sprinkleBonus:'Extra sprinkles / attack',strikeHeightBonus:'Extra vertical sword height',waveWard:'Waves turned aside',swordWidthBonus:'Wider swords',blockBounty:'Points per block',secondWind:'Second Wind',attackHasteMs:'Waves sooner',chainSprinkles:'Sprinkles on big chains'};
const effectValue=(kind,value)=>kind==='secondWind'?(value?'ready each encounter':'none'):kind==='attackHasteMs'?'−'+value/1000+'s':kind==='breakerBonus'?'+'+Number((value*100).toFixed(2))+' pp':kind==='scorePercent'?'+'+value+'%':kind==='attackDelayMs'?'+'+value/1000+'s':'+'+value;
// a reward card's one line: what you will have once you take it
const SHORT={scorePercent:n=>`+${n}% clear points`,chainBonus:n=>`+${n} points per chain stage`,breakerBonus:n=>`+${Math.round(n*100)}% breakers`,attackDelayMs:n=>`Timed waves ${n/1000}s slower`,sprinkleBonus:n=>`+${n} sprinkle${n===1?'':'s'} on every attack`,strikeHeightBonus:n=>`Upright swords ${n} row${n===1?'':'s'} taller`,waveWard:n=>`First ${n===1?'wave':n+' waves'} each encounter turned aside`,swordWidthBonus:n=>`Upright swords ${n} column${n===1?'':'s'} wider`,blockBounty:n=>`+${n} points per block`,secondWind:()=>'Clears your top rows once per encounter',attackHasteMs:n=>`timed waves ${n/1000}s sooner`,chainSprinkles:n=>`+${n} sprinkles on ×3+ chains`};
const shortGives=u=>(u.effects||[]).map(e=>SHORT[e.kind]?.(e.next??e.amount??0)).filter(Boolean).join(', ');
const rankEffects=(u,preview=false)=>u.effects.map(e=>esc(effectName[e.kind])+': '+esc(effectValue(e.kind,e.current))+(preview?' → '+esc(effectValue(e.kind,e.next)):'')).join('<br>');
const opponentBoard=v=>v.opponent?'<section class="challenge-board rogue-opponent next-right"><div class="board-header"><div><strong>'+esc(v.opponent.name)+'</strong><span>'+esc(v.opponent.patternName?v.opponent.patternName+' · ':'')+esc(v.opponent.difficulty)+'</span></div><div class="next-piece"><span>NEXT</span><canvas id="rogue-opponent-next" aria-label="Opponent next pair"></canvas></div></div><div class="board-frame"><canvas id="rogue-opponent-board" aria-label="Opponent board, six columns and thirteen rows"></canvas><div class="board-banner ol-banner" id="rogue-banner-1"></div></div><p id="rogue-opponent-status" class="fine-print rogue-foot"></p></section>':'';


export function createRogueUI({host,prefs,read,save,sound,showSettings,getPool}){
 const scope=new AbortController(),$=q=>host.querySelector(q),held=new Map();
 let run=null,disposed=false,paused=false,raf=0,last=0,acc=0,saveTick=0,lastPhase='',storageError='',lastFeedback='',log=createComboLog({limit:400}),ending=null,feedVersion=-1,coachState=null;
 const set=(q,value)=>{const el=$(q);if(el&&el.textContent!==String(value))el.textContent=String(value);};
 function report(message){storageError=message;set('#rogue-save-status',message);}
 function persist(){if(!run)return true;try{if(!save(SAVE_KEY,serializeRun(run))){report('Could not save in this browser. Export your run to keep it.');return false;}saveTick=run.tick;storageError='';set('#rogue-save-status','Saved in this browser.');return true;}catch(e){report(e.message);return false;}}
 function download(value){const url=URL.createObjectURL(new Blob([value],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='swords-pass-solo-run.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function releaseAll(){held.clear();if(run?.phase==='playing'&&run.game.players[0].fast)inputRun(run,['fastOff']);acc=0;}
 function pause(value=true){if(!run||run.phase!=='playing')return;paused=value;releaseAll();persist();renderOverlay();}
 function execute(fn){try{fn();if(run){processEvents();persist();drawScreen();}}catch(e){paused=true;report(e.message);renderOverlay();}}
 function processEvents(){for(const e of run.events)event(e);if(run.game)closeCombos(run.game);}
 // one run event: sounds, the combo feed, and the combo name over the board that made it
 function event(e){if(e.type==='scored')lastFeedback=`+${e.points} points · combo ×${e.chain}`;else if(e.type==='puzzle-breaking'){const d=e.detail;if(d.side===0)sound('clear',d.chain);flash(d.side,log.step(d.side,stepOf(d)));}else if(e.type==='puzzle-hit'&&e.detail.side===0)sound('hit');else if(e.type==='puzzle-lock'&&e.detail.side===0)sound('lock');else if(e.type==='attack-queued')log.add('wave',{chain:0,steps:[]},{wave:(e.wave??0)+1,pattern:e.patternName});else if(e.type==='run-won')sound('win');else if(e.type==='run-lost')sound('end');}
 function closeCombos(game){for(const s of [0,1])if(game.players[s]&&!(game.players[s].chain|0))log.close(s);}
 function flash(side,c){const b=$('#rogue-banner-'+side);if(!b||c.chain<2)return;b.textContent=comboName(c.chain)+' ×'+c.chain;b.className='board-banner ol-banner active tier-'+Math.min(6,c.chain);clearTimeout(b.t);b.t=setTimeout(()=>b.classList.remove('active'),950);}
 function feedHTML(){const them=runView(run).opponent?.name??'Rival';return log.entries.length?log.entries.slice(0,12).map(c=>c.who==='wave'?`<div class="chain-entry theirs wave${c.shown?'':' enter'}"><b class="chain-n">≈</b><div><strong>Wave ${c.wave||''}</strong><small>${esc(c.pattern||'An attack')} incoming</small></div></div>`+((c.shown=true),''):comboHTML(c,{who:c.who===0?'You':them,mine:c.who===0})).join(''):'<p class="muted">No combos yet.</p>';}
 const fit=()=>{const f=$('.rogue-playfield');if(f)fitBoards(f,{board:'.challenge-board',room:()=>(innerWidth-2*300-180)/(f.classList.contains('duel')?2:1)});};
 window.addEventListener('resize',fit,{signal:scope.signal});
 function setup(){
  run=null;paused=false;held.clear();lastPhase='';const stored=read(SAVE_KEY,null);let live=false;try{live=!!stored&&!isTerminal(restoreRun(stored));}catch{}
  host.innerHTML=`<section class="panel rogue-setup"><h2>${esc(DEFAULT_CLIMB.name)}</h2><p class="muted">${esc(DEFAULT_CLIMB.description)}</p><p class="muted">A fresh board each encounter. Upgrades and your score carry forward. Filling column 4 ends the run.</p><label class="field-label" for="rogue-seed">Run seed</label><input id="rogue-seed" type="number" min="0" max="4294967295" step="1" value="${crypto.getRandomValues(new Uint32Array(1))[0]}"><div class="button-row"><button class="primary" id="rogue-new">New run</button>${live?'<button id="rogue-resume-saved">Resume saved run</button>':''}</div><div class="button-row rogue-setup-tools"><details class="rogue-more"><summary>More</summary><div class="rogue-more-menu"><button id="rogue-settings">Controls & feel</button>${stored?'<button id="rogue-export-saved">Export saved run</button>':''}<button id="rogue-import">Import run</button></div></details></div><input id="rogue-file" type="file" accept="application/json,.json" hidden><p id="rogue-save-status" class="fine-print" role="status">${esc(storageError||'Your run saves as you go. Leave any time and pick it up later.')}</p></section>`;
  globalThis.scrapsAdventure?.setup?.(host);$('#rogue-new').onclick=()=>{const field=$('#rogue-seed');if(field.value===''||!field.reportValidity())return;const begin=()=>execute(()=>{run=createClimb({seed:Number(field.value),rules:prefs.rules,pool:getPool()});paused=false;});const A=globalThis.scrapsAsk;if(!live)return begin();if(A)A({eyebrow:'A RUN IS SAVED',title:'Start over?',body:'Your saved run will be replaced. Export it first to keep it.',yes:'Start new run'}).then(ok=>{if(ok)begin();});else if(confirm('Replace the saved run? Export it first if you want to keep it.'))begin();};
  $('#rogue-resume-saved')?.addEventListener('click',()=>execute(()=>{const loaded=restoreRun(stored);run=loaded;paused=run.phase==='playing';}));
  $('#rogue-export-saved')?.addEventListener('click',()=>download(typeof stored==='string'?stored:JSON.stringify(stored)));
  $('#rogue-settings').onclick=showSettings;host.querySelectorAll('.rogue-more-menu button').forEach(b=>b.addEventListener('click',()=>b.closest('details').open=false));$('#rogue-import').onclick=()=>$('#rogue-file').click();
  $('#rogue-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>MAX_SAVE_BYTES){report('Run files must be no larger than 2 MB.');return;}try{const text=await file.text();if(disposed)return;const loaded=restoreRun(text);if(live&&!confirm('Replace the saved run with this imported run?'))return;execute(()=>{run=loaded;paused=run.phase==='playing';});}catch(error){report(error.message);}};
 }
 function drawScreen(){
  if(!run)return;ending=null;lastPhase=run.phase;const v=present(runView(run));held.clear();acc=0;
  host.innerHTML=`<section class="room-heading game-heading"><div><p class="eyebrow">${v.kind==='climb'?`ENDLESS CLIMB / ${v.encounter.bonus?'BONUS AT '+v.depth:'ENCOUNTER '+v.encounter.depth}`:`SOLO RUN / ${v.roomIndex+1} OF ${v.roomCount}`}</p><h1>${esc(v.encounter.name)}</h1></div><div class="match-tools"><button id="rogue-save-exit">Save & exit</button>${v.finished?'':'<button id="rogue-abandon">End run</button>'}<button id="rogue-export">Export</button></div></section><div class="rogue-layout"><section class="table-surface"><div id="rogue-stage"></div></section><aside class="panel rogue-sidebar"><p class="eyebrow">YOUR RUN</p>${v.kind==='climb'?`<p class="fine-print">${esc(v.encounter.band)}</p>`:''}<p>Score <strong id="rogue-score">${v.totalScore}</strong></p><p>Blocks <strong id="rogue-blocks">${v.totalBlocks}</strong></p><p>Best combo <strong id="rogue-combo">×${v.bestCombo||1}</strong></p><div class="divider"></div><h3>Upgrades</h3><div>${v.inventory.length?v.inventory.map(u=>`<p><strong>${esc(u.name)} · Rank ${u.stacks}</strong><br><span class="fine-print">${rankEffects(u)}</span></p>`).join(''):'<p class="muted">Complete an encounter to choose your first upgrade.</p>'}</div><div class="divider"></div><p class="fine-print">Seed ${v.seed}</p><p id="rogue-save-status" class="fine-print" role="status">${esc(storageError||'Saved in this browser.')}</p></aside></div>`;
  $('#rogue-save-exit').onclick=()=>{pause(true);if(persist())setup();};$('#rogue-export').onclick=()=>{pause(true);try{download(serializeRun(run));}catch(e){report(e.message);}};
  if($('#rogue-abandon'))$('#rogue-abandon').onclick=()=>{pause(true);const A=globalThis.scrapsAsk;if(A)A({title:'End this run?',body:'Your score is final, and the run goes into your road log.',yes:'End run'}).then(ok=>{if(ok)execute(()=>abandonRun(run));});else if(confirm('End this run?'))execute(()=>abandonRun(run));};
  const stage=$('#rogue-stage');
  if(v.phase==='route'){
   stage.innerHTML=`<p class="eyebrow">ENCOUNTER ${v.depth+1}</p><h2>Choose your next challenge.</h2><p class="muted">Complete an objective to advance. Your handling stays the same.</p><div class="rogue-rewards">${v.paths.map(e=>`<button data-climb-path="${e.id}"><strong>${esc(e.name)}${e.rare?' · RARE':''}</strong><span>${esc(objective(e))}</span><span>${e.kind==='duel'?esc(e.opponent.name)+(e.opponent.title?' · '+esc(e.opponent.title):'')+(e.opponent.sword?' · wields '+esc(e.opponent.sword.name):''):'Timed challenge'} · ${clock(e.durationMs)}</span><small>+${e.rewardPoints} score${e.optional?' · bonus: '+esc(objectiveLabel(e.optional))+' (+'+e.bonusPoints+')':''}</small></button>`).join('')}</div>`;
   for(const b of stage.querySelectorAll('[data-climb-path]'))b.onclick=()=>execute(()=>choosePath(run,b.dataset.climbPath));
  }else if(v.phase==='result'){
   stage.innerHTML=`<p class="eyebrow">CHECKPOINT BONUS</p><h2>Keep climbing.</h2><p class="muted">${v.reason==='skipped'?'Bonus skipped.':'Bonus missed.'} Your run continues from depth ${v.depth}.</p><button class="primary" id="climb-continue">Next encounter</button>`;
   $('#climb-continue').onclick=()=>execute(()=>continueClimb(run));
  }else if(v.phase==='ready'){

   stage.innerHTML=`<p class="eyebrow">${v.encounter.bonus?'CHECKPOINT BONUS':'ENCOUNTER '+(v.roomIndex+1)}</p><h2>${esc(objective(v.encounter))}</h2>${v.encounter.objective?`<p class="rogue-hint">${esc(objectiveHint(v.encounter.objective))}</p>`:''}<p class="muted">${esc(v.encounter.description)}</p><p>Time limit: ${clock(v.encounter.durationMs)}</p>${v.encounter.optional?`<p>Optional bonus: ${esc(objectiveLabel(v.encounter.optional))} · +${v.encounter.bonusPoints} points</p>`:''}${v.encounter.bonus?'<p class="muted">Bonus failure ends this round only. Your climb continues.</p>':''}${v.opponent?`<p class="muted">${esc(v.opponent.name)}${v.opponent.title?', '+esc(v.opponent.title.toLowerCase()):''} · ${esc(v.opponent.difficulty)}${v.opponent.sword?' · wields '+esc(v.opponent.sword.name):''}. Your breaks attack their board; theirs attack yours.</p>`:`<p class="muted">Attacks queue for your next placement. Each wave: ${v.encounter.attacks.swords} sword(s), ${v.encounter.attacks.width}×${v.encounter.attacks.length}, plus ${v.encounter.attacks.sprinkles} sprinkles.</p>`}<p class="fine-print">Fresh board · upgrades apply for this encounter.</p><button class="primary" id="rogue-start">Start encounter</button>${v.encounter.bonus?'<button id="climb-skip">Skip bonus</button>':''}`;
   $('#climb-skip')?.addEventListener('click',()=>execute(()=>skipBonus(run)));
   $('#rogue-start').onclick=()=>execute(()=>{log=createComboLog({limit:400});ending=null;startEncounter(run);paused=false;lastFeedback='';sound('start');});
  }else if(v.phase==='reward'){
   stage.innerHTML=`<p class="eyebrow">ENCOUNTER COMPLETE</p><h2>Choose your reward.</h2>${v.lastResult?`<p class="fine-print">${v.lastResult.score} points this round · +${v.lastResult.completionPoints} completion bonus${v.lastResult.optionalComplete?' · optional objective completed':''}</p>`:''}<p class="muted">${v.offers.every(u=>u.pointReward)?'Bank the points and continue.':'Upgrades take effect on the next board and last for this run.'}</p><div class="rogue-rewards">${v.offers.map(u=>`<button data-rogue-reward="${u.id}" data-rarity="${u.rarity??'common'}" title="${esc(u.description)}"><strong>${esc(u.name)}</strong><span class="relic-gives">${u.pointReward?'+50 run points':esc(shortGives(u))}</span></button>`).join('')}</div>`;
   for(const b of stage.querySelectorAll('[data-rogue-reward]'))b.onclick=()=>execute(()=>chooseReward(run,b.dataset.rogueReward));
  }else if(v.finished){
   stage.innerHTML=`<p class="eyebrow">${v.phase==='won'?'RUN COMPLETE':v.phase==='abandoned'?'RUN ENDED':'RUN OVER'}</p><h2>${v.totalScore.toLocaleString()} points</h2><p class="muted">${v.reason==='board'?'Column 4 filled.':v.reason==='time'?'The objective was not reached before time ran out.':v.phase==='won'?'Every encounter completed.':'Your run has ended.'}</p>${v.kind==='climb'?'<p class="fine-print">Recent encounters</p>':''}<ol>${v.results.map(result=>`<li>${esc(result.name??run.content.encounters.find(e=>e.id===result.encounterId).name)}: ${result.success?'complete':'failed'} · ${result.score} points</li>`).join('')}</ol><button class="primary" id="rogue-again">Back to solo runs</button>`;$('#rogue-again').onclick=setup;
  }else{
   const keys=`${esc(keyLabel([].concat(prefs.keys.left)[0]??''))} / ${esc(keyLabel([].concat(prefs.keys.right)[0]??''))} move · ${esc(keyLabel([].concat(prefs.keys.ccw)[0]??''))} / ${esc(keyLabel([].concat(prefs.keys.cw)[0]??''))} rotate · ${esc(keyLabel([].concat(prefs.keys.drop)[0]??''))} fast fall`;
   // the boards in the middle; the objective, combos and controls in a rail on the left, your run on the right
   stage.innerHTML=`<div class="rogue-arena"><aside class="rogue-rail"><section class="ol-card rogue-goal"><p class="eyebrow">OBJECTIVE</p><strong>${esc(objective(v.encounter))}</strong><div class="goal-bar" aria-hidden="true"><i id="rogue-goal-fill"></i></div><span id="rogue-progress"></span>${v.encounter.objective&&!v.opponent?`<small>${esc(objectiveHint(v.encounter.objective))}</small>`:''}<p class="fine-print" id="climb-optional"></p></section><div class="challenge-hud rogue-hud2"><div><span>TIME LEFT</span><strong id="rogue-clock"></strong></div><div><span>${v.opponent?'INCOMING':'NEXT WAVE'}</span><strong id="rogue-wave"></strong></div></div><section class="ol-card rogue-feed"><p class="eyebrow">${v.opponent?'COMBOS':'COMBOS & WAVES'}</p><div id="rogue-feed" class="chain-log" aria-live="polite">${feedHTML()}</div></section><p id="rogue-incoming" class="fine-print"></p><p id="rogue-feedback" role="status" class="fine-print"></p><div class="button-row"><button id="rogue-pause">Pause</button><button id="rogue-controls">Controls & feel</button></div><p class="fine-print rogue-keys">${keys}</p></aside><div class="rogue-playfield ${v.opponent?'duel':''}"><div class="challenge-board rogue-mine"><div class="board-header"><div><strong>You</strong><span id="rogue-my-sub">${v.opponent?'Keep column 4 open':esc(v.encounter.name)}</span></div><div class="next-piece"><span>NEXT</span><canvas id="rogue-next" aria-label="Next pair"></canvas></div></div><div class="board-frame"><canvas id="rogue-board" aria-label="Solo run board, six columns and thirteen rows"></canvas><div class="board-banner ol-banner" id="rogue-banner-0"></div><div class="goal-pop" id="rogue-goal-pop" role="status"></div></div><p id="rogue-my-status" class="fine-print rogue-foot"></p></div>${opponentBoard(v)}<div id="rogue-overlay" class="game-overlay"></div></div><div class="touch-controls challenge-touch">${[['left','←'],['ccw','↶'],['cw','↷'],['right','→'],['drop','Fast fall']].map(([a,label])=>`<button data-rogue-action="${a}" aria-label="${esc(a==='ccw'?'Rotate counterclockwise':a==='cw'?'Rotate clockwise':a==='drop'?'Fast fall':'Move '+a)}">${label}</button>`).join('')}</div></div>`;
   feedVersion=-1;coachState=null;fit();requestAnimationFrame(fit);
   $('#rogue-pause').onclick=()=>pause(!paused);$('#rogue-controls').onclick=showSettings;
   for(const b of stage.querySelectorAll('[data-rogue-action]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press('touch-'+b.dataset.rogueAction,b.dataset.rogueAction);};b.onpointerup=b.onpointercancel=()=>release('touch-'+b.dataset.rogueAction);}
   renderOverlay();paint(0);
  }
  globalThis.scrapsAdventure?.screen?.(host,v);
 }
 // The encounter is over: hold the final boards and say what happened before moving on.
 function outro(){
  const v=present(runView(run)),r=v.lastResult??v.results?.[v.results.length-1],won=!['lost','result','abandoned'].includes(v.phase),o=v.opponent,overlay=$('#rogue-overlay');lastPhase=run.phase;
  if(!overlay)return drawScreen();
  const label=won?(o?'VICTORY':'CLEARED'):v.phase==='result'?'BONUS MISSED':v.reason==='time'?"TIME'S UP":'DEFEATED';
  const head=won?(o?`${esc(o.name)} is beaten.`:'Objective complete.'):v.phase==='result'?'Your climb goes on.':v.reason==='time'?'The objective slipped away.':o&&o.board?.dead?'You both went down.':'Column 4 filled.';
  const line=r?`${Math.max(0,(r.score??0)-(r.completionPoints??0)).toLocaleString()} points this round${r.completionPoints?` · +${r.completionPoints} for the win`:''}${r.optionalComplete?' · bonus done':''}`:'';
  const mine=log.entries.filter(c=>c.who===0),best=Math.max(1,...mine.map(c=>c.chain)),swords=mine.reduce((n,c)=>n+c.steps.reduce((k,st)=>k+st.s.length,0),0),bigs=mine.filter(c=>c.chain>=3).length;
  overlay.classList.add('shown');overlay.innerHTML=`<div class="pause-card endgame rogue-outro ${won?'win':'loss'}"><div class="eg-banner"><span>${label}</span></div><h2>${head}</h2>${line?`<p class="muted">${line}</p>`:''}<dl class="eg-stats"><div><dt>Best combo</dt><dd>${best>1?'×'+best:'–'}</dd></div><div><dt>Swords sent</dt><dd>${swords}</dd></div><div><dt>Combos ×3+</dt><dd>${bigs}</dd></div>${o?'':`<div><dt>Waves</dt><dd>${log.entries.filter(c=>c.who==='wave').length}</dd></div>`}</dl><div class="eg-unlocks" hidden></div><button class="primary" id="rogue-outro-next" disabled>${won?'Claim your reward':v.phase==='lost'?'See how far you got':'Continue'}</button></div>`;
  if(won&&!run.events.some(e=>e.type==='run-won'))sound('win');else if(v.phase==='result')sound('end');
  const next=$('#rogue-outro-next');next.onclick=()=>drawScreen();setTimeout(()=>{if(next.isConnected){next.disabled=false;next.focus();}},700);
 }
 function renderOverlay(){const overlay=$('#rogue-overlay');if(!overlay||overlay.querySelector('.rogue-outro'))return;overlay.classList.toggle('shown',paused);overlay.innerHTML=paused?'<div class="pause-card"><h2>Run paused.</h2><button class="primary" id="rogue-continue">Continue</button></div>':'';$('#rogue-continue')?.addEventListener('click',()=>pause(false));set('#rogue-pause',paused?'Continue':'Pause');}
 function press(code,action){if(!run||run.phase!=='playing')return;if(action==='pause'){pause(!paused);return;}if(paused||held.has(code))return;held.set(code,{action,next:run.tick*TICK_MS+run.game.rules.repeatDelayMs});try{inputRun(run,[action==='drop'?'fastOn':action]);if(['left','right','cw','ccw'].includes(action))sound(action==='cw'||action==='ccw'?'rotate':'move');}catch(e){pause(true);report(e.message);}}
 function release(code){const h=held.get(code);held.delete(code);if(h?.action==='drop'&&run?.phase==='playing')inputRun(run,['fastOff']);}
 function tick(){
  for(const h of held.values()){if(['left','right'].includes(h.action)&&run.tick*TICK_MS>=h.next){inputRun(run,[h.action]);h.next=run.tick*TICK_MS+run.game.rules.repeatMs;}if(run.engineVersion<10&&h.action==='drop'&&run.game.players[0].phase==='fall'&&!run.game.players[0].fast)inputRun(run,['fastOn']);}
  stepRun(run);processEvents();if(run.phase!==lastPhase){paused=false;persist();if(lastPhase==='playing'){if(run.game){try{coach(runView(run));}catch{}ending={po:createPlayout(run.game),acc:0,shown:false,won:!['lost','result','abandoned'].includes(run.phase)};lastPhase=run.phase;}else outro();}else drawScreen();}else if(run.tick-saveTick>=60)persist();
 }
 // the encounter is decided: the last combo and attacks finish on screen, a finisher if it earned one, then the outro
 function playout(delta){const e=ending,po=e.po;if(!po.done){e.acc+=delta;while(e.acc>=TICK_MS&&!po.done){e.acc-=TICK_MS;po.step(TICK_MS);for(const ev of po.state.events)event({type:'puzzle-'+ev.type,detail:ev});closeCombos(po.state);}return;}
  if(e.shown)return;e.shown=true;const opp=runView(run).opponent,w=e.won?0:opp?1:null;
  showFinisher(w===null?null:finisherOf(log.entries.find(c=>c.who===w)),{who:w===0?'You':opp?.name??'',reduced:prefs.reduced,prefs}).then(()=>{if(ending===e){ending=null;outro();}});}
 // Objective coaching: a bar that fills, and a word over your board whenever you get closer
 const fraction=p=>p.items?(p.kind==='all'?Math.min(...p.items.map(fraction)):Math.max(...p.items.map(fraction))):p.target?p.value/p.target:0;
 const leaves=p=>p.items?p.items.flatMap(leaves):[p];
 function pop(text,big=false){const el=$('#rogue-goal-pop');if(!el)return;el.textContent=text;el.className='goal-pop show'+(big?' big':'');clearTimeout(el.t);el.t=setTimeout(()=>el.classList.remove('show'),big?2200:1500);globalThis.scrapsSfx?.(big?'fullclear':'fuse',big?1:8,prefs);}
 function coach(v){
  const op=v.objectiveProgress;if(!op)return;const f=$('#rogue-goal-fill');if(f)f.style.width=Math.round(Math.min(1,fraction(op))*100)+'%';
  const now=leaves(op),was=coachState;coachState={complete:op.complete,leaves:now.map(l=>({...l}))};if(!was)return;
  if(op.complete&&!was.complete){pop(v.opponent?'Rival down':'Objective complete',true);return;}
  now.forEach((l,i)=>{const b=was.leaves[i];if(!b||l.value<=b.value||l.complete&&b.complete)return;const k=l.kind,q=t=>Math.floor(t/l.target*4);
   if(k==='sword')pop(`${swordSize(l.value)} sword!${l.complete?'':' · need '+swordSize(l.target)}`);
   else if(k==='combo')pop(`×${l.value} combo${l.complete?'':' · need ×'+l.target}`);
   else if((k==='blocks'||k==='score')&&q(l.value)>q(b.value)&&q(l.value)<4)pop(`${q(l.value)*25}% there`);
   else if(k==='survive'&&(q(l.value)>q(b.value)&&q(l.value)===2))pop('Halfway');
   else if(k==='survive'&&l.target-l.value<=10000&&l.target-b.value>10000)pop('10 seconds!');});
 }
 function paint(time){
  if(!run||(run.phase!=='playing'&&!ending))return;const v=runView(run);if(ending){const st=ending.po.state;v.board=st.players[0];if(v.opponent)v.opponent.board=st.players[1];}
  drawBoard($('#rogue-board'),v.board,{time,gravityMs:v.rules.gravityMs,fastFallMs:v.rules.fastFallMs,renderAheadMs:paused?0:acc,ghost:prefs.ghost,reduced:prefs.reduced});drawNext($('#rogue-next'),v.nextPair);
  set('#rogue-score',v.totalScore.toLocaleString());set('#rogue-blocks',v.totalBlocks);set('#rogue-combo','×'+(v.bestCombo||1));set('#rogue-clock',clock(v.remainingMs));set('#rogue-progress',v.objectiveProgress?objectiveStatus(v.objectiveProgress):v.opponent?(v.opponent.board.dead?'Defeated':'Defeat opponent'):v.encounter.objective.kind==='survive'?clock(v.progress)+' / '+clock(v.encounter.objective.target):v.progress+' / '+v.encounter.objective.target);set('#rogue-wave',v.opponent?v.queuedWaves+' queued':v.nextWave.held?'Queue full':clock(v.nextWave.inMs));
  set('#climb-optional',v.optionalProgress?'Optional: '+objectiveStatus(v.optionalProgress)+(v.optionalProgress.complete?' · complete':''):'');
  if(v.opponent?.board){drawBoard($('#rogue-opponent-board'),v.opponent.board,{time,gravityMs:v.rules.gravityMs,fastFallMs:v.rules.fastFallMs,renderAheadMs:paused?0:acc,reduced:prefs.reduced});drawNext($('#rogue-opponent-next'),v.opponent.nextPair);set('#rogue-opponent-status',v.opponent.queuedWaves+' attacks queued');}
  if(!ending)coach(v);if(feedVersion!==log.version){feedVersion=log.version;const f=$('#rogue-feed');if(f)f.innerHTML=feedHTML();}set('#rogue-my-status',v.queuedWaves?v.queuedWaves+' queued · land a pair':'');set('#rogue-incoming',v.opponent?v.queuedWaves+' attacks queued · '+v.sentSwords+' swords and '+v.sentSprinkles+' sprinkles sent':v.queuedWaves+' waves queued · next pattern: '+v.nextWave.patternName);set('#rogue-feedback',lastFeedback);
 }
 function frame(time){if(disposed)return;const delta=Math.max(0,Math.min(100,time-(last||time)));last=time;if(ending)playout(delta);if(run?.phase==='playing'&&!paused){acc+=delta;try{while(acc>=TICK_MS&&run.phase==='playing'){acc-=TICK_MS;tick();}}catch(e){paused=true;report(e.message);renderOverlay();}}else acc=0;paint(time);raf=requestAnimationFrame(frame);}
 window.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||document.activeElement?.matches('input,select,textarea')||!run||run.phase!=='playing')return;const action=actionFor(prefs.keys,e.code);if(!action)return;e.preventDefault();if(!e.repeat)press(e.code,action);},{signal:scope.signal});
 window.addEventListener('keyup',e=>release(e.code),{signal:scope.signal});window.addEventListener('blur',()=>pause(true),{signal:scope.signal});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause(true);},{signal:scope.signal});window.addEventListener('pagehide',()=>{releaseAll();persist();},{signal:scope.signal});
 globalThis.__scrapsRogue={get run(){return run;}};
 setup();raf=requestAnimationFrame(frame);
 return {inPlay:()=>!!run&&(run.phase==='playing'||!!ending),beforeLeave(){if(!run)return true;paused=true;releaseAll();renderOverlay();return persist();},isActive:()=>!!run&&!isTerminal(run),pause:()=>pause(true),getState:()=>run?{...runView(run),paused,tick:run.tick}:null,destroy(){releaseAll();persist();disposed=true;scope.abort();cancelAnimationFrame(raf);}};
}
